// swift-tools-version:5.9
import PackageDescription

let package = Package(
	name: "tauri-plugin-screenshare",
	// Matches bundle.iOS.minimumSystemVersion in tauri.conf.json. ReplayKit
	// broadcast extensions need 14+, so 15 is comfortably clear.
	platforms: [.iOS(.v15)],
	products: [
		.library(
			name: "tauri-plugin-screenshare",
			type: .static,
			targets: ["tauri-plugin-screenshare"]
		)
	],
	dependencies: [
		// Generated by `tauri ios init` next to the app project.
		.package(name: "Tauri", path: "../.tauri/tauri-api"),
		// The native publisher. The broadcast extension target links this too —
		// it is where LKSampleHandler comes from.
		.package(url: "https://github.com/livekit/client-sdk-swift.git", from: "2.6.0"),
	],
	targets: [
		.target(
			name: "tauri-plugin-screenshare",
			dependencies: [
				.byName(name: "Tauri"),
				.product(name: "LiveKit", package: "client-sdk-swift"),
			],
			path: "Sources"
		)
	]
)
